-- Уникальность event_id и версии объекта; наличие родительского hub и события с тем же аудитом.
SELECT count(*) AS n FROM (SELECT event_id AS k FROM {{target:oil_dds__sat_field}} GROUP BY event_id HAVING event_id IS NULL OR count(*)>1 UNION ALL SELECT field_hk AS k FROM {{target:oil_dds__sat_field}} GROUP BY field_hk,entity_version HAVING field_hk IS NULL OR entity_version IS NULL OR count(*)>1 UNION ALL SELECT s.event_id AS k FROM {{target:oil_dds__sat_field}} s LEFT JOIN {{target:oil_dds__hub_field}} h ON h.field_hk=s.field_hk LEFT JOIN {{target:oil_dds__event}} e ON e.event_id=s.event_id WHERE h.field_hk IS NULL OR e.event_id IS NULL OR s.load_dts IS DISTINCT FROM e.load_dts OR s.record_source IS DISTINCT FROM e.record_source) q;
